const config = $input.first().json;
const errors = [];
if (!/^([^/\s]+)\/([^/\s]+)$/.test(String(config.githubRepo || '').trim())) errors.push('githubRepo must use owner/repository.');
if (!['EN', 'FR'].includes(String(config.language || '').toUpperCase())) errors.push('language must be EN or FR.');
if (!/^https:\/\//.test(String(config.destinationWebhookUrl || ''))) errors.push('destinationWebhookUrl must be an HTTPS URL.');
const valid = errors.length === 0;
const nextSteps = valid ? ['Create GITHUB_TOKEN with read access to the selected repository.', 'Set ANTHROPIC_API_KEY in n8n.', 'Import the complete workflow and run it manually once before activating the schedule.'] : ['Correct the fields in Configuration.', 'Run this preflight again.'];
return [{ json: { valid, errors, configuration: { githubRepo: config.githubRepo, language: String(config.language || '').toUpperCase(), destinationWebhookUrl: config.destinationWebhookUrl }, nextSteps } }];
